def combinations(n, k):
    if k < 0 or k > n:
        return 0
    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

def calculate_ratio(n):
    if n < 4:
        return 0
    f_g = combinations(n, 3)
    g_g = combinations(n, 4)

    if f_g == 0:
        return float('inf')

    return (g_g**3) / (f_g**4)

ratios = {}
for n in range(4, 16):
    r = calculate_ratio(n)
    ratios[n] = r
    print(f"n={n}: Ratio = {r}")

