from math import comb

def R(n):
    if n < 4:
        return 0
    # R(n) = g(K_n)^3 / f(K_n)^4
    g_n = comb(n, 4)
    f_n = comb(n, 3)
    return (g_n**3) / (f_n**4)

# Test small values and check monotonicity
n_values = range(4, 12)
results = {n: R(n) for n in n_values}

print("R(n) values:")
for n, r in results.items():
    print(f"R({n}) = {r}")

print("\nSuccessive Ratio R(n+1)/R(n):")
ratios = {}
for n in range(4, 11):
    ratio = results[n+1] / results[n]
    ratios[n] = ratio
    print(f"R({n+1})/R({n}) = {ratio}")
